import { cac } from "../src/index.ts";

let allPassed = true;

// Test 1: Default without args - both names should have default
const cli1 = cac();
cli1.option('-b, --base-url <url>', 'Set base URL', { default: 'https://github.com' });
const r1 = cli1.parse(['node', 'bin']);
if (r1.options.baseUrl !== 'https://github.com' || r1.options.b !== 'https://github.com') {
  console.log('FAIL Test 1: Default without args');
  allPassed = false;
} else {
  console.log('PASS Test 1: Default without args');
}

// Test 2: Long flag parsed - both names should have parsed value
const cli2 = cac();
cli2.option('-b, --base-url <url>', 'Set base URL', { default: 'https://github.com' });
const r2 = cli2.parse(['node', 'bin', '--base-url', 'https://gitlab.com']);
if (r2.options.baseUrl !== 'https://gitlab.com' || r2.options.b !== 'https://gitlab.com') {
  console.log('FAIL Test 2: Long flag parsed');
  console.log('  baseUrl:', r2.options.baseUrl, 'b:', r2.options.b);
  allPassed = false;
} else {
  console.log('PASS Test 2: Long flag parsed');
}

// Test 3: Short flag parsed - both names should have parsed value
const cli3 = cac();
cli3.option('-b, --base-url <url>', 'Set base URL', { default: 'https://github.com' });
const r3 = cli3.parse(['node', 'bin', '-b', 'https://gitlab.com']);
if (r3.options.baseUrl !== 'https://gitlab.com' || r3.options.b !== 'https://gitlab.com') {
  console.log('FAIL Test 3: Short flag parsed');
  console.log('  baseUrl:', r3.options.baseUrl, 'b:', r3.options.b);
  allPassed = false;
} else {
  console.log('PASS Test 3: Short flag parsed');
}

// Test 4: Boolean flag with aliases
const cli4 = cac();
cli4.option('-f, --force', 'Force mode', { default: false });
const r4 = cli4.parse(['node', 'bin', '-f']);
if (r4.options.force !== true || r4.options.f !== true) {
  console.log('FAIL Test 4: Boolean flag');
  allPassed = false;
} else {
  console.log('PASS Test 4: Boolean flag');
}

// Test 5: Multiple options
const cli5 = cac();
cli5.option('-b, --base-url <url>', 'Set base URL', { default: 'https://github.com' });
cli5.option('-f, --force', 'Force mode', { default: false });
const r5 = cli5.parse(['node', 'bin', '--base-url', 'https://gitlab.com', '-f']);
if (r5.options.baseUrl !== 'https://gitlab.com' || r5.options.b !== 'https://gitlab.com' ||
    r5.options.force !== true || r5.options.f !== true) {
  console.log('FAIL Test 5: Multiple options');
  allPassed = false;
} else {
  console.log('PASS Test 5: Multiple options');
}

if (allPassed) {
  console.log('\nAll tests passed!');
} else {
  console.log('\nSome tests failed!');
  process.exit(1);
}

